<?php
require_once "config/app.php";wajib_login();if(is_admin())redirect("admin/dashboard.php");
if($_SERVER['REQUEST_METHOD']!=='POST')redirect("kontestan.php");
$id=(int)($_POST['kontestan_id']??0);$jumlah=(int)($_POST['jumlah']??0);
if($jumlah<1||$jumlah>100){flash("Jumlah suara harus 1 sampai 100.","danger");redirect("kontestan.php");}
$s=$conn->prepare("SELECT * FROM kontestan WHERE id=?");$s->bind_param("i",$id);$s->execute();$k=$s->get_result()->fetch_assoc();$periode=periode_aktif($conn);
if(!$k||!$periode){flash("Kontestan tidak tersedia atau voting sedang ditutup.","danger");redirect("kontestan.php");}
$s=$conn->prepare("SELECT id FROM voting WHERE user_id=? AND kategori=?");$s->bind_param("is",$_SESSION['user']['id'],$k['kategori']);$s->execute();if($s->get_result()->num_rows){flash("Kamu sudah memilih kategori ini.","danger");redirect("kontestan.php");}
$harga=(int)$periode['harga_per_suara'];$total=$jumlah*$harga;
$_SESSION['checkout']=['kontestan_id'=>$id,'jumlah'=>$jumlah,'total'=>$total,'periode_id'=>$periode['id']];
$page_title="Pembayaran voting";include "includes/header.php";?>
<div class="container py-5"><div class="row justify-content-center"><div class="col-lg-7"><div class="panel p-4"><div class="eyebrow">Pembayaran dukungan</div><h1 class="section-title">Selesaikan pembayaran</h1><p class="small-muted">Silakan transfer sesuai nominal berikut, lalu unggah bukti pembayaran.</p><div class="soft-section rounded-3 p-3 mb-3"><div class="d-flex justify-content-between"><span>Kontestan</span><strong><?=e($k['nama'])?></strong></div><div class="d-flex justify-content-between"><span>Jumlah suara</span><strong><?=$jumlah?></strong></div><div class="d-flex justify-content-between"><span>Harga per suara</span><strong>Rp <?=number_format($harga,0,',','.')?></strong></div><hr><div class="d-flex justify-content-between"><strong>Total transfer</strong><strong class="stat-number fs-3">Rp <?=number_format($total,0,',','.')?></strong></div></div><div class="panel p-3 mb-3"><strong>Rekening tujuan</strong><p class="mb-1 fs-5 fw-bold"><?=e($periode['rekening'] ?: 'Belum diatur admin')?></p><p class="small-muted mb-0">Atas nama: <?=e($periode['pemilik_rekening'] ?: 'Belum diatur admin')?></p><?php if(!$periode['rekening']):?><span class="text-danger small">Jangan transfer sebelum informasi rekening resmi diisi admin.</span><?php endif;?></div><form action="proses/upload-pembayaran.php" method="post" enctype="multipart/form-data"><label class="form-label">Nama pengirim</label><input class="form-control mb-3" name="nama_pengirim" required><label class="form-label">Bukti transfer (JPG/PNG/PDF, maks. 3 MB)</label><input class="form-control mb-3" type="file" name="bukti" accept=".jpg,.jpeg,.png,.pdf" required><button class="btn btn-maroon w-100">Kirim bukti pembayaran</button></form></div></div></div></div>
